#!/usr/bin/env python3
"""Read the native transcripts of headless probe cases: python3 extract_all.py results.tsv [results2.tsv ...].

Each line of a results file is "<case name> <case directory>". For every case this prints the resolved model, the recorded effort
and the client version of the main session and of every subagent transcript below it, counting each assistant message id once (a
message spans several transcript rows, one per content block), plus the number of transcript lines holding the Ultracode reminder text.
"""
import collections
import glob
import json
import os
import sys

PROJECTS = os.path.expanduser("~/.claude/projects")


def summarize(path, cutoff=None):
    """Unique assistant messages of one transcript, up to an optional UTC ISO cutoff (rows carry ISO timestamps)."""
    seen, versions, stamps, reminder = {}, set(), [], 0
    for line in open(path, errors="replace"):
        try:
            row = json.loads(line)
        except ValueError:
            continue
        stamp = str(row.get("timestamp", ""))
        if cutoff and stamp > cutoff:
            continue
        if row.get("version"):
            versions.add(row["version"])
        if stamp:
            stamps.append(stamp)
        message = row.get("message") or {}
        if message.get("role") == "assistant" and message.get("model") and message["model"] != "<synthetic>":
            seen.setdefault(message.get("id"), (message["model"], str(row.get("effort"))))
        if "Ultracode is on: optimize" in line:
            reminder += 1
    return {"messages": len(seen),
            "models": dict(collections.Counter(v[0] for v in seen.values())),
            "efforts": dict(collections.Counter(v[1] for v in seen.values())),
            "versions": sorted(versions),
            "utc": [min(stamps), max(stamps)] if stamps else None,
            "reminder_lines": reminder}


def case_paths(name, case_dir):
    """The main transcript and the subagent transcripts of one headless case, or None when the client kept none."""
    encoded = case_dir.replace("/", "-").replace("_", "-")
    projects = [d for d in glob.glob(os.path.join(PROJECTS, "*")) if os.path.basename(d) == encoded] or \
               [d for d in glob.glob(os.path.join(PROJECTS, "*")) if os.path.basename(d).endswith("case-" + name)]
    if not projects:
        return None
    mains = sorted(glob.glob(os.path.join(projects[0], "*.jsonl")), key=os.path.getmtime)
    return (mains[-1] if mains else None), sorted(glob.glob(os.path.join(projects[0], "*", "subagents", "agent-*.jsonl")))


def main(results_files):
    for results in results_files:
        for entry in open(results):
            name, case_dir = entry.split()
            paths = case_paths(name, case_dir)
            if not paths:
                print(name, "| no transcript directory")
                continue
            main_path, sub_paths = paths
            print(name, "| main:", summarize(main_path) if main_path else None, "| subagents:", [summarize(p) for p in sub_paths])


if __name__ == "__main__":
    main(sys.argv[1:])
